"""Operational dashboard for AFTERBELL."""
PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AFTERBELL | Risk console</title><style>
:root{color-scheme:dark;--bg:#0b1014;--panel:#121b21;--raised:#18242b;--line:#29383e;--text:#e8efeb;--muted:#96aaa7;--mint:#a7e3be;--amber:#efc37d;--red:#f49292;--blue:#89bce2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.45 system-ui,sans-serif}button,select,input{font:inherit;color:inherit;background:var(--raised);border:1px solid var(--line);border-radius:5px;padding:6px 9px}button{cursor:pointer}button:hover,button.active{border-color:var(--mint);color:var(--mint)}a{color:var(--mint)}header{position:sticky;top:0;z-index:5;background:#0c1419f5;border-bottom:1px solid var(--line);padding:12px 18px;display:flex;align-items:center;gap:13px;flex-wrap:wrap}header strong{letter-spacing:.13em;font-size:15px}header small{margin-left:auto;color:var(--muted)}main{max-width:1700px;margin:auto;padding:14px;display:grid;gap:12px}.tag{display:inline-block;font:11px ui-monospace,monospace;padding:3px 6px;border:1px solid var(--line);border-radius:4px;color:var(--muted)}.PASS,.CALIBRATED,.OK{color:var(--mint)}.BLOCK,.FAILED,.STALE{color:var(--red)}.WARN,.REDUCE{color:var(--amber)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.panel,.metric{background:var(--panel);border:1px solid var(--line);border-radius:8px;min-width:0}.metric{padding:13px}.label,h2{font-size:10px;font-weight:650;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.value{font:600 24px ui-monospace,monospace;letter-spacing:-.05em;margin:8px 0}.note{font-size:11px;color:var(--muted);overflow-wrap:anywhere}h2{margin:0}.ph{padding:11px 13px;display:flex;gap:9px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.body{padding:13px}.workspace{display:grid;grid-template-columns:1.45fr 1fr 1fr;gap:12px}.span2{grid-column:span 2}.full{grid-column:1/-1}.stack{display:grid;gap:12px;align-content:start}.row{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}.facts{display:grid;grid-template-columns:1fr 1fr;gap:11px}.fact{padding:8px 0;border-bottom:1px solid var(--line)}.fact b{display:block;font:14px ui-monospace,monospace;margin-top:5px}.gate{display:grid;grid-template-columns:28px 1fr auto;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)}.gate details{grid-column:2/-1;color:var(--muted);font-size:11px}.gate summary{cursor:pointer}.bar{height:5px;background:var(--line);margin:5px 0;border-radius:2px}.bar i{display:block;height:100%;background:var(--mint)}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:12px}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}th{font-size:10px;color:var(--muted);font-weight:500}td{font-variant-numeric:tabular-nums}svg{display:block;width:100%;height:180px}.chartlegend{display:flex;gap:18px;font:11px ui-monospace,monospace;padding:10px 13px}.receipt{border-bottom:1px solid var(--line);padding:10px 13px}.receipt summary{cursor:pointer;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.receipt p{font-size:12px}.hash{font:10px ui-monospace,monospace;color:var(--muted);overflow-wrap:anywhere}.receipts{max-height:410px;overflow:auto}.console{display:flex;gap:8px;flex-wrap:wrap}.console label{display:grid;gap:4px;color:var(--muted);font-size:11px}.console input{width:125px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.6 ui-monospace,monospace;color:var(--muted);max-height:330px;overflow:auto}footer{font-size:11px;color:var(--muted);padding:6px}.statusline{padding:8px 12px;border:1px solid var(--line);border-radius:5px;font-size:11px;color:var(--muted)}.links{display:flex;gap:15px;flex-wrap:wrap}.blue{color:var(--blue)}@media(max-width:1150px){.metrics{grid-template-columns:repeat(3,1fr)}.workspace{grid-template-columns:1fr 1fr}.span2{grid-column:1/-1}}@media(max-width:650px){.metrics{grid-template-columns:1fr 1fr}.workspace{grid-template-columns:1fr}.span2{grid-column:auto}header small{margin-left:0}.value{font-size:20px}.ph{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><header><strong>◔ AFTERBELL</strong><span class="tag">RISK CONSOLE</span><span class="tag">READ ONLY</span><span id="connection" class="tag">CONNECTING</span><small id="updated">Waiting for recorded state</small><a href="https://github.com/Jennycruzy/afterbell">Source ↗</a></header><main>
<div class="metrics" id="metrics"></div><div class="statusline" id="freshness">Loading market evidence…</div>
<div class="workspace">
<section class="panel span2"><div class="ph"><h2>NVDAB · Basis & reference age</h2><div id="ranges"><button data-range="1">1H</button> <button data-range="24">24H</button> <button class="active" data-range="0">ALL</button></div></div><div class="chartlegend"><span class="blue">Basis · bps</span><span class="PASS">Reference age · hours</span><span id="points" class="note"></span></div><svg id="chart" viewBox="0 0 900 180" role="img" aria-label="Recorded basis versus reference age"></svg><div class="body note" id="chartnote"></div></section>
<section class="panel"><div class="ph"><h2>Latest guard decision</h2><span id="decisiontag"></span></div><div class="body" id="decision"></div></section>
<section class="panel"><div class="ph"><h2>Seven protection checks</h2><span class="note">Recorded outcome</span></div><div class="body" id="gates"></div></section>
<section class="panel"><div class="ph"><h2>Decision sizing</h2><span class="note">min of ceilings</span></div><div class="body" id="sizing"></div></section>
<section class="panel"><div class="ph"><h2>Exposure & authorization</h2><span class="tag">P7</span></div><div class="body" id="exposure"></div></section>
<section class="panel full"><div class="ph"><h2>Market measurements</h2><span class="note">Recorded public books · regular-session baselines</span></div><div class="tablewrap"><table><thead><tr><th>Pair / underlying</th><th>Status</th><th>Token mid</th><th>Reference</th><th>Basis bps</th><th>Half-spread bps</th><th>Depth ±1%</th><th>Walk $5k bps</th><th>Spread / RTH</th><th>Depth / RTH</th><th>Baseline samples</th></tr></thead><tbody id="markets"></tbody></table></div></section>
<section class="panel"><div class="ph"><h2>Baseline coverage</h2><span id="baselineflag"></span></div><div class="body" id="baselines"></div></section>
<section class="panel"><div class="ph"><h2>Policy review</h2><span class="tag">HUMAN REVIEW</span></div><div class="body" id="policy"></div></section>
<section class="panel"><div class="ph"><h2>Recorder & backup</h2><span id="backuptag"></span></div><div class="body" id="operations"></div></section>
<section class="panel span2"><div class="ph"><h2>Decision console</h2><span class="tag">RECORDED REPLAY</span></div><div class="body"><div class="console"><label>Pair<select id="symbol"></select></label><label>Outcome<select id="outcome"><option>ALL</option><option>PASS</option><option>WARN</option><option>REDUCE</option><option>BLOCK</option></select></label><button id="inspect">Inspect latest matching receipt</button><button id="download">Download receipt JSON</button></div><div id="inspectresult" class="note" style="margin-top:12px">Inspect the recorded request, its measurements, and the resulting size.</div></div></section>
<section class="panel"><div class="ph"><h2>Evaluation evidence</h2><span class="note">Generated report</span></div><div class="body" id="evidence"></div></section>
<section class="panel span2"><div class="ph"><h2>Receipt activity</h2><span id="receiptcount" class="note"></span></div><div class="receipts" id="receipts"></div></section>
<section class="panel"><div class="ph"><h2>Execution trace · recorded acceptance</h2></div><div class="body" id="acceptance"></div></section>
<section class="panel full"><div class="ph"><h2>Calibration report & audit identifiers</h2></div><div class="body"><div class="links"><a href="https://github.com/Jennycruzy/afterbell/blob/main/docs/calibration.md">Calibration report ↗</a><a href="https://github.com/Jennycruzy/afterbell/blob/main/docs/evaluation.md">Evaluation methodology ↗</a><a href="https://github.com/Jennycruzy/afterbell/blob/main/docs/live-acceptance.md">Acceptance evidence ↗</a></div><details><summary>Recorded calibration table</summary><pre id="calreport"></pre></details><div id="hashes" class="hash"></div></div></section>
</div><footer>AFTERBELL · Calendar-aware risk controls for tokenized equities. Current corporate-action status is checked; advance notice remains partial. Counterparty composition remains inconclusive pending comparable coverage.</footer></main>
<script>
(()=>{'use strict';let state=null,range=0,selected=null;const $=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=2)=>v==null?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:d}),badge=v=>'<span class="tag '+(['PASS','WARN','REDUCE','BLOCK','CALIBRATED','OK','FAILED','STALE'].includes(v)?v:'')+'">'+esc(v)+'</span>',fact=(k,v)=>'<div class="fact"><span class="label">'+esc(k)+'</span><b>'+esc(v)+'</b></div>',time=v=>{let t=Date.parse(v);return Number.isFinite(t)?new Date(t).toLocaleString():'Unknown'},seconds=v=>{let t=Date.parse(v);return Number.isFinite(t)?Math.max(0,(Date.now()-t)/1000):Infinity},age=s=>!Number.isFinite(s)?'Unknown':Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m';const names={P1:'Market clock',P2:'Liquidity',P3:'Price agreement',P4:'Corporate action',P5:'Instrument identity',P6:'Contract check',P7:'Aggregate exposure'};
function draw(){let h=(state.history||[]).filter(x=>Number.isFinite(Number(x.basis_bps))&&Number.isFinite(Number(x.reference_age_s)));if(range&&h.length){let end=Date.parse(h[h.length-1].ts);h=h.filter(x=>Date.parse(x.ts)>=end-range*3600000)}$('points').textContent=h.length+' paired samples';if(h.length<2){$('chart').innerHTML='<text x="450" y="90" text-anchor="middle" fill="#96aaa7">Insufficient paired samples in this window</text>';return}const ts=h.map(x=>Date.parse(x.ts)),start=Math.min(...ts),end=Math.max(...ts);let out='';for(let y of [20,60,100,140])out+='<line x1="55" x2="845" y1="'+y+'" y2="'+y+'" stroke="#29383e"/>';for(const [key,col,div] of [['basis_bps','#89bce2',1],['reference_age_s','#a7e3be',3600]]){let values=h.map(x=>x[key]/div),lo=Math.min(...values),hi=Math.max(...values);let dots=values.map((v,i)=>{let x=55+790*(ts[i]-start)/(end-start||1),y=140-120*(v-lo)/(hi-lo||1);return '<circle cx="'+x+'" cy="'+y+'" r="2" fill="'+col+'"><title>'+esc(time(h[i].ts))+' · '+fmt(v)+(div===1?' bps':' hours')+'</title></circle>'}).join('');out+=dots+'<text x="'+(div===1?2:850)+'" y="15" fill="'+col+'" font-size="10">'+fmt(hi,1)+'</text>'}out+='<text x="55" y="170" fill="#96aaa7" font-size="10">'+esc(time(h[0].ts))+'</text><text x="845" y="170" text-anchor="end" fill="#96aaa7" font-size="10">'+esc(time(h[h.length-1].ts))+'</text>';$('chart').innerHTML=out;$('chartnote').textContent='Separate scales · timestamp-positioned observations · gaps are not interpolated. Hover a point for its value.'}
function matching(){return(state.receipts||[]).filter(r=>($('symbol').value==='ALL'||r.symbol===$('symbol').value)&&($('outcome').value==='ALL'||r.decision===$('outcome').value))}
function receipts(){let rows=matching();$('receiptcount').textContent=rows.length+' of '+(state.receipts||[]).length+' loaded';$('receipts').innerHTML=rows.map(r=>'<details class="receipt"><summary>'+badge(r.decision)+'<b>'+esc(r.symbol)+'</b><span class="note">#'+esc(r.seq)+' · '+esc(time(r.ts))+' · $'+fmt(r.requested?.notional)+' → $'+fmt(r.allowed_notional)+'</span></summary><p>'+esc(r.rationale)+'</p><div class="hash">Hash '+esc(r.hash)+'<br>Previous '+esc(r.prev_hash)+'</div></details>').join('')||'<div class="body note">No matching receipts in the loaded window.</div>'}
function freshness(){if(!state)return;let s=seconds(state.guard?.ts),archive=seconds(state.generated_at);$('connection').textContent=s>180?'GUARD STALE':'GUARD RECENT';$('connection').className='tag '+(s>180?'STALE':'OK');$('updated').textContent='Guard '+age(s)+' ago · refresh 10s';$('freshness').textContent='Market archive snapshot: '+time(state.generated_at)+' ('+age(archive)+' ago). Guard: '+time(state.guard?.ts)+'. '+(state.build_status==='WARMING'?'History indexing; market tables are pending.':'')+(archive>600?' Market snapshot is stale.':'')}
function render(d){state=d;let g=d.guard||{},p=d.policy||{},m=g.measurements||{},sy=d.symbols||[],base=sy.filter(x=>x.baseline_status==='CALIBRATED').length;let ageSeconds=g.reference_ts?seconds(g.reference_ts):g.reference_age_s;let ms=[['Reference market',g.market_state||d.clock?.state,'Reference age '+age(ageSeconds)],['Permitted size','$'+fmt(g.allowed_notional),'Requested $'+fmt(g.requested_notional)],['Binding gate',g.binding_constraint||'Unknown',g.status||'No decision'],['Baseline coverage',sy.length?base+'/'+sy.length:'Pending','RTH minimum '+fmt(p.min_rth_samples,0)+'/symbol'],['Execution',p.executor_enabled===true?'Enabled':p.executor_enabled===false?'Disabled':'Unknown','Policy '+(p.status==='UNCALIBRATED'?'review pending':p.status)],['Latest receipt',g.receipt_seq?'#'+g.receipt_seq:'Pending',time(g.ts)]];$('metrics').innerHTML=ms.map(x=>'<article class="metric"><div class="label">'+esc(x[0])+'</div><div class="value">'+esc(x[1])+'</div><div class="note">'+esc(x[2])+'</div></article>').join('');$('decisiontag').innerHTML=badge(g.status||'UNKNOWN');$('decision').innerHTML='<div class="value">$'+fmt(g.allowed_notional)+'</div><p>'+esc(g.rationale||g.note)+'</p><div class="note">Observed '+esc(time(g.ts))+'</div>';
$('gates').innerHTML=Object.entries(names).map(([k,v])=>'<div class="gate"><span class="note">'+k+'</span><b>'+v+'</b>'+badge(g.gates?.[k]||'UNKNOWN')+'<details><summary>Details</summary>'+esc(g.gate_detail?.[k]||'No recorded detail')+'</details></div>').join('');let receipt=(d.receipts||[]).find(r=>r.seq===g.receipt_seq),factors=receipt?.gate_factors||{};$('sizing').innerHTML=Object.entries(names).map(([k,v])=>{let f=factors[k];return '<div class="fact"><div class="row"><span>'+k+' · '+v+'</span><span>'+ (f==null?'Factor not loaded':fmt(f,3)+'× · $'+fmt(Math.min(g.requested_notional,p.base_notional*f)))+'</span></div>'+(f==null?'':'<div class="bar"><i style="width:'+Math.max(0,Math.min(100,f*100))+'%"></i></div>')+'</div>'}).join('')+'<p class="note">Allowed = min(request, base notional × tightest gate factor). A blocking gate sets allowed size to zero.</p>';
$('exposure').innerHTML='<div class="facts">'+fact('Snapshot',m.exposure_check||'Unknown')+fact('Gross ceiling','$'+fmt(p.max_gross_usdt))+fact('Snapshot required',p.require_snapshot===true?'Yes':p.require_snapshot===false?'No':'Unknown')+fact('Position balance','Not supplied')+'</div><p class="note">'+esc(g.gate_detail?.P7||'Awaiting exposure evidence')+'</p><p class="note">Signed authorization → supported MCP client → child receipt. No account credential is held by this console.</p>';
$('markets').innerHTML=sy.map(s=>'<tr><td><b>'+esc(s.symbol)+'</b><div class="note">'+esc(s.underlying)+'</div></td><td>'+badge(s.status)+'</td><td>'+fmt(s.mid)+'</td><td>'+fmt(s.reference_price)+'</td><td>'+fmt(s.basis_bps,1)+'</td><td>'+fmt(s.half_spread_bps,3)+'</td><td>$'+fmt(s.depth_1pct,0)+'</td><td>'+fmt(s.walk_5k_bps,1)+'</td><td>'+fmt(s.spread_ratio)+'×</td><td>'+fmt(s.liquidity_ratio==null?null:s.liquidity_ratio*100,0)+'%</td><td>'+fmt(s.n_rth,0)+' / '+fmt(p.min_rth_samples,0)+'</td></tr>').join('');
$('baselineflag').innerHTML=badge(sy.length&&base===sy.length?'CALIBRATED':'PENDING');$('baselines').innerHTML=sy.map(s=>fact(s.asset,fmt(s.n_rth,0)+' RTH · '+fmt(s.n_by_state?.CLOSED_HOLIDAY,0)+' holiday')).join('')+'<p class="note">Coverage describes measured baseline denominators. Threshold approval is tracked separately.</p>';$('policy').innerHTML='<div class="value">'+(p.status==='UNCALIBRATED'?'Review pending':esc(p.status))+'</div><p class="note">Raw policy status: '+esc(p.status)+'. The policy retains its hypothesis thresholds. Sample completeness does not automatically promote those limits.</p><a href="https://github.com/Jennycruzy/afterbell/blob/main/config/policy.yaml">Inspect policy values ↗</a>';
let b=d.backup||{},bst=b.status==='OK'&&seconds(b.ts)>7200?'STALE':b.status||'UNKNOWN';$('backuptag').innerHTML=badge(bst);$('operations').innerHTML=fact('Verified through',b.covered_through)+fact('Last backup',time(b.ts))+fact('Retention',b.retention_days?b.retention_days+' days':'Unknown')+'<p class="note">Stable-file verification. The active raw archive is excluded from verification. Status older than two hours is stale.</p>';
let ev=d.evaluation||{};$('evidence').innerHTML=Object.entries(ev).filter(([k])=>/Adversarial attacks|Payloads that raised|False-positive|Positive controls/.test(k)).map(([k,v])=>fact(k,v)).join('')+'<p class="note">False-positive cohort: repeated full-base-size requests during regular hours with normal measured books. This is not arbitrary order-flow accuracy.</p>';
let a=d.acceptance||{};$('acceptance').innerHTML=fact('Historical order',a.order_id)+fact('Quantity',a.quantity)+fact('Notional',a.notional)+'<p class="note">Guard decision → signed authorization → supported-client submission → finalized child receipt. This is a recorded acceptance event, not an open position.</p>';
$('calreport').textContent=d.calibration_markdown||'Report unavailable';$('hashes').textContent='Policy '+(p.sha256||'Unknown')+' · Registry '+(d.registry_sha256||'Unknown')+' · Ledger head '+(d.ledger_head||'Unknown');let prev=$('symbol').value;$('symbol').innerHTML=['ALL',...new Set((d.receipts||[]).map(r=>r.symbol))].map(s=>'<option>'+esc(s)+'</option>').join('');if([...$('symbol').options].some(o=>o.value===prev))$('symbol').value=prev;draw();receipts();freshness()}
$('inspect').onclick=()=>{selected=matching()[0]||null;$('inspectresult').textContent=selected?'Receipt #'+selected.seq+' · '+selected.rationale:'No matching receipt available.'};$('download').onclick=()=>{let r=selected||matching()[0];if(!r)return;let url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='afterbell-receipt-'+r.seq+'.json';a.click();URL.revokeObjectURL(url)};$('symbol').onchange=$('outcome').onchange=()=>{selected=null;receipts()};document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=Number(b.dataset.range);document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));if(state)draw()});
async function tick(){try{let r=await fetch('/api/state',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);render(await r.json())}catch(e){$('connection').textContent='DISCONNECTED';$('connection').className='tag STALE';$('freshness').textContent='Refresh failed. Displayed values are retained observations; check their timestamps.'}}tick();setInterval(tick,10000);setInterval(freshness,1000);
})();
</script></body></html>"""
